-- Scheme Master register: one per-scheme LATERAL aggregate for the three viability statistics
-- CANDIDATE ONLY - NOT APPLIED. Generated by scripts/scheme-master-perf-candidate/build.mjs from supabase/migrations/20261019134900_tb2_costing_view_permission_gate.sql. Do not edit by hand; re-run the generator.
-- Issue #211 (B): v_costing_scheme_master_register intermittently exceeds the statement timeout (57014) on the Pricing Policy Manager Scheme Master workspace.
--
-- WHAT CHANGES: the three correlated subqueries over costing.sku_scheme_viability_snapshot (count(*), count(DISTINCT period_start), max(period_start)) become ONE
--   LEFT JOIN LATERAL aggregate per scheme row. The 31 other columns, all names, order, types, NULL handling, security_invoker=true and the outer
--   "where (select public.fn_costing_view_allowed())" gate are textually unchanged. No ORDER BY is added (the client orders by scheme_name).
-- WHY THIS SHAPE: measured live, SELECT-only (issue #211, 8 Nov 2026): baseline warm 231.433 ms (206,906 shared hits), this shape 124.916 ms (102,883 hits),
--   all 7 scheme rows identical on the 3 changed columns; the global GROUP BY alternative was slower (2,941.849 ms, temp sort) and is NOT used.
-- NOT CHANGED: grants (CREATE OR REPLACE VIEW keeps ACL and reloptions), the table, indexes, RLS, any RPC, any client code, any flag.
-- APPLY ONLY after the owner's approval gates in README.md (all-column parity, grant/permission parity, plan timing, backup of the TB2 definition).
-- ROLLBACK: scheme_master_register_rollback_tb2.sql (restores the TB2 text byte for byte).
--
-- Precondition: fail closed if the live view is not exactly the expected pre-change shape (drift would mean this candidate was reviewed against different SQL).
do $pre$
declare v_def text; v_opts text[]; v_cols int;
begin
  select pg_get_viewdef('public.v_costing_scheme_master_register'::regclass, true), c.reloptions into v_def, v_opts from pg_class c where c.oid = 'public.v_costing_scheme_master_register'::regclass;
  select count(*) into v_cols from pg_attribute where attrelid = 'public.v_costing_scheme_master_register'::regclass and attnum > 0 and not attisdropped;
  if v_cols <> 34 then raise exception 'scheme-master candidate precondition: expected 34 columns, found %', v_cols; end if;
  if v_opts is null or not (v_opts @> array['security_invoker=true']) then raise exception 'scheme-master candidate precondition: security_invoker=true missing'; end if;
  if v_def !~ 'fn_costing_view_allowed' then raise exception 'scheme-master candidate precondition: permission gate missing'; end if;
  if (select count(*) from regexp_matches(v_def, 'sku_scheme_viability_snapshot', 'g')) <> 3 then raise exception 'scheme-master candidate precondition: expected exactly 3 viability snapshot references (pre-change shape)'; end if;
end
$pre$;

create or replace view public.v_costing_scheme_master_register with (security_invoker=true) as
select q.* from (
SELECT id AS scheme_id,
    scheme_name,
    paid_qty,
    free_qty,
    (paid_qty + free_qty) AS total_qty,
        CASE
            WHEN (paid_qty > (0)::numeric) THEN (free_qty / paid_qty)
            ELSE NULL::numeric
        END AS free_per_paid_ratio,
        CASE
            WHEN ((paid_qty + free_qty) > (0)::numeric) THEN ((free_qty / (paid_qty + free_qty)) * (100)::numeric)
            ELSE NULL::numeric
        END AS effective_free_discount_percent,
    is_active,
    is_system_defined,
    remarks,
    approval_reference,
    ( SELECT count(*) AS count
           FROM costing.sku_scheme_policy p
          WHERE (p.scheme_id = sm.id)) AS direct_policy_count,
    ( SELECT count(*) AS count
           FROM costing.sku_scheme_policy p
          WHERE ((p.scheme_id = sm.id) AND (p.is_active = true))) AS active_direct_policy_count,
    ( SELECT count(*) AS count
           FROM costing.scheme_policy_rules r
          WHERE (r.scheme_id = sm.id)) AS hierarchy_rule_count,
    ( SELECT count(*) AS count
           FROM costing.scheme_policy_rules r
          WHERE ((r.scheme_id = sm.id) AND (r.is_active = true))) AS active_hierarchy_rule_count,
    ( SELECT count(*) AS count
           FROM costing.scheme_policy_rules r
          WHERE (r.replace_from_scheme_id = sm.id)) AS replacement_reference_count,
    ( SELECT count(*) AS count
           FROM costing.scheme_policy_rules r
          WHERE ((r.replace_from_scheme_id = sm.id) AND (r.is_active = true))) AS active_replacement_reference_count,
    viab.vs_snapshot_count AS viability_snapshot_count,
    viab.vs_period_count AS viability_snapshot_period_count,
    viab.vs_latest_period AS latest_viability_snapshot_period,
    (NOT is_system_defined) AS can_edit_metadata,
    (is_active AND (NOT is_system_defined) AND (NOT (EXISTS ( SELECT 1
           FROM costing.sku_scheme_policy p
          WHERE ((p.scheme_id = sm.id) AND (p.is_active = true))))) AND (NOT (EXISTS ( SELECT 1
           FROM costing.scheme_policy_rules r
          WHERE ((r.scheme_id = sm.id) AND (r.is_active = true))))) AND (NOT (EXISTS ( SELECT 1
           FROM costing.scheme_policy_rules r
          WHERE ((r.replace_from_scheme_id = sm.id) AND (r.is_active = true)))))) AS can_deactivate,
    ((NOT is_active) AND (NOT is_system_defined)) AS can_reactivate,
    created_at,
    created_by,
    updated_at,
    updated_by,
    metadata_update_reason,
    deactivated_at,
    deactivated_by,
    deactivation_reason,
    reactivated_at,
    reactivated_by,
    reactivation_reason
   FROM costing.scheme_master sm
   LEFT JOIN LATERAL (
     SELECT count(*) AS vs_snapshot_count,
            count(DISTINCT s.period_start) AS vs_period_count,
            max(s.period_start) AS vs_latest_period
       FROM costing.sku_scheme_viability_snapshot s
      WHERE s.scheme_id = sm.id
   ) viab ON true
) q
where (select public.fn_costing_view_allowed());
